        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
      });

      if (loginRes.ok) {
        const loginData = await loginRes.json();
        localStorage.setItem("user", JSON.stringify(loginData.user));
        localStorage.setItem("affiliateLink", affiliateLink);

        toast({
          title: "✓ Account created! Redirecting to domain registration...",
        });

        // Redirect to domain registration page
        setTimeout(() => {
          window.location.href = `https://domain.rentapog.com/`;
        }, 1000);
      } else {
        toast({
          title: "✓ Account created! Please log in to continue.",
        });
        setTimeout(() => {
          window.location.href = `https://domain.rentapog.com/`;
        }, 1500);
      }
    } catch (err) {
      setError("An error occurred. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex items-center justify-center bg-gradient-to-b from-slate-50 to-white px-4 py-8">
      <Card className="w-full max-w-lg shadow-xl">
        <CardHeader>
          <CardTitle className="text-center text-2xl">Create Your Account</CardTitle>
          <p className="text-center text-slate-600 text-sm mt-1">Register to start renting domains</p>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleRegister} className="space-y-4">
            {error && (
              <div className="bg-red-50 border border-red-200 rounded-lg p-3 text-sm text-red-700 flex items-start gap-2">
                <AlertCircle className="h-4 w-4 shrink-0 mt-0.5" />
                {error}
              </div>
            )}

            <div className="space-y-2">
              <label className="text-sm font-medium">Name</label>
              <div className="relative">
                <User className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                <Input
                  type="text"
                  placeholder="Your name"
                  className="pl-9"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  required
                  data-testid="input-name"
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium">Affiliate Username</label>
              <div className="relative">
                <User className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                <Input
                  type="text"
                  placeholder="yourname (your affiliate code)"
                  className="pl-9"
                  value={username}
                  onChange={(e) => setUsername(e.target.value.toLowerCase().replace(/\s+/g, ''))}
                  required
                  data-testid="input-username"
                />
              </div>
              <p className="text-xs text-slate-500">This will be your personal affiliate code for sharing</p>
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium">Email</label>
              <div className="relative">
                <Mail className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                <Input
                  type="email"
                  placeholder="you@example.com"
                  className="pl-9"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  required
                  data-testid="input-email"
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium">Password</label>
              <div className="relative">
                <Lock className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                <Input
                  type="password"
                  placeholder="••••••••"
                  className="pl-9"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                  data-testid="input-password"
                />
              </div>
            </div>

            <div className="border-t pt-4">
              <h3 className="text-sm font-semibold text-slate-700 mb-3 flex items-center gap-2">
                <MapPin className="h-4 w-4" />
                Address Information
              </h3>

              <div className="space-y-3">
                <div className="space-y-1 relative">
                  <label className="text-xs font-medium text-slate-600">Street Address</label>
                  <Input
                    type="text"
                    placeholder="Type your address..."
                    value={address}
                    onChange={(e) => handleAddressChange(e.target.value)}
                    onFocus={() => addressSuggestions.length > 0 && setShowAddressSuggestions(true)}
                    onBlur={() => setTimeout(() => setShowAddressSuggestions(false), 200)}
                    data-testid="input-address"
                  />
                  {showAddressSuggestions && addressSuggestions.length > 0 && (
                    <div className="absolute top-full left-0 right-0 mt-1 bg-white border border-slate-300 rounded-md shadow-lg z-10 max-h-40 overflow-y-auto">
                      {addressSuggestions.map((suggestion, idx) => (
                        <button
                          key={idx}
                          type="button"
                          className="w-full text-left px-3 py-2 hover:bg-slate-100 text-sm text-slate-700 border-b last:border-b-0"
                          onClick={() => selectAddress(suggestion)}
                        >
                          {suggestion.display_name?.substring(0, 60)}...
                        </button>
                      ))}
                    </div>
                  )}
                </div>

                <div className="grid grid-cols-2 gap-2">
                  <div className="space-y-1">
                    <label className="text-xs font-medium text-slate-600">City</label>
                    <Input
                      type="text"
                      placeholder="City"
                      value={city}
                      onChange={(e) => setCity(e.target.value)}
                      data-testid="input-city"
                    />
                  </div>
                  <div className="space-y-1 relative">
                    <label className="text-xs font-medium text-slate-600">State/Province</label>
                    <Input
                      type="text"
                      placeholder="Type to search..."
                      value={state}
                      onChange={(e) => {
                        setState(e.target.value);
                        setShowStateSuggestions(true);
                      }}
                      onFocus={() => setShowStateSuggestions(true)}
                      onBlur={() => setTimeout(() => setShowStateSuggestions(false), 200)}
                      data-testid="input-state"
                    />
                    {showStateSuggestions && filteredStates.length > 0 && (
                      <div className="absolute top-full left-0 right-0 mt-1 bg-white border border-slate-300 rounded-md shadow-lg z-10 max-h-40 overflow-y-auto">
                        {filteredStates.map(s => (
                          <button
                            key={s}
                            type="button"
                            className="w-full text-left px-3 py-2 hover:bg-slate-100 text-sm"
                            onClick={() => {
                              setState(s);
                              setShowStateSuggestions(false);
                            }}
                          >
                            {s}
                          </button>
                        ))}
                      </div>
                    )}
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-2">
                  <div className="space-y-1">
                    <label className="text-xs font-medium text-slate-600">ZIP Code</label>
                    <Input
                      type="text"
                      placeholder="12345"
                      value={zip}
                      onChange={(e) => setZip(e.target.value)}
                      data-testid="input-zip"
                    />
                  </div>
                  <div className="space-y-1 relative">
                    <label className="text-xs font-medium text-slate-600">Country</label>
                    <Input
                      type="text"
                      placeholder="Type to search..."
                      value={country}
                      onChange={(e) => {
                        setCountry(e.target.value);
                        setState("");
                        setShowCountrySuggestions(true);
                      }}
                      onFocus={() => setShowCountrySuggestions(true)}
                      onBlur={() => setTimeout(() => setShowCountrySuggestions(false), 200)}
                      data-testid="input-country"
                    />
                    {showCountrySuggestions && filteredCountries.length > 0 && (
                      <div className="absolute top-full left-0 right-0 mt-1 bg-white border border-slate-300 rounded-md shadow-lg z-10 max-h-40 overflow-y-auto">
                        {filteredCountries.map(c => (
                          <button
                            key={c}
                            type="button"
                            className="w-full text-left px-3 py-2 hover:bg-slate-100 text-sm"
                            onClick={() => {
                              setCountry(c);
                              setState("");
                              setShowCountrySuggestions(false);
                            }}
                          >
                            {c}
                          </button>
                        ))}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </div>

            {affiliateLink && affiliateLink !== "admin" && (
              <div className="space-y-2">
                <label className="text-sm font-medium">Affiliate Link</label>
                <div className="relative">
                  <LinkIcon className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                  <Input
                    type="text"
                    placeholder="Affiliate link"
                    className="pl-9 bg-gray-50"
                    value={affiliateLink}
                    disabled
                    readOnly
                  />
                </div>
                {referrerName && (
                  <p className="text-xs text-green-600">Referred by: <span className="font-semibold">{referrerName}</span></p>
                )}
              </div>
            )}

            <Button type="submit" className="w-full h-12" disabled={loading}>
              {loading ? "Creating account..." : "Create Account"}
            </Button>

            <p className="text-center text-sm text-muted-foreground">
              Already have an account?{" "}
              <a href="/login" className="text-primary font-semibold hover:underline">
                Sign in
              </a>
            </p>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

