import { storage } from "./storage";
import { db } from "./db";
import { insertEmailLeadSchema, insertAffiliateSaleSchema, insertUserSchema, users, emailSchedules, emailLeads, DOMAIN_NICHES, rentalContracts } from "@shared/schema";
