import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { AlertCircle, CheckCircle, Lock } from "lucide-react";
import { useToast } from "@/hooks/use-toast";

export default function ResetPassword() {
  const [token, setToken] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState(false);
  const { toast } = useToast();

  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const tokenParam = urlParams.get("token");
    if (tokenParam) {
      setToken(tokenParam);
    }
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");

    if (!token) {
      setError("Invalid or missing reset token. Please request a new reset link.");
      return;
    }

    if (!newPassword || !confirmPassword) {
      setError("Please fill in all fields");
      return;
    }

    if (newPassword.length < 6) {
      setError("Password must be at least 6 characters");
      return;
    }

    if (newPassword !== confirmPassword) {
      setError("Passwords do not match");
      return;
    }

    setLoading(true);
    try {
      const res = await fetch("/api/auth/reset-password", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ token, newPassword }),
      });

      const data = await res.json();

      if (res.ok) {
        setSuccess(true);
        toast({
          title: "Password Reset!",
          description: "Your password has been changed successfully.",
        });
      } else {
        setError(data.message || "Failed to reset password");
      }
    } catch (err) {
      setError("Connection error. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  if (success) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-900 to-slate-950 flex items-center justify-center p-4">
        <Card className="w-full max-w-md bg-slate-800 border-green-500/30">
          <CardHeader>
            <CardTitle className="text-2xl text-green-300 flex items-center gap-2">
              <CheckCircle className="h-6 w-6" />
              Password Reset Successfully!
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <p className="text-slate-300">
              Your password has been changed. You can now log in with your new password.
            </p>
            <Button
              onClick={() => window.location.href = "https://backend.rentapog.com/login"}
              className="w-full bg-cyan-600 hover:bg-cyan-700 text-white font-bold h-10"
            >
              Go to Login
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (!token) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-900 to-slate-950 flex items-center justify-center p-4">
        <Card className="w-full max-w-md bg-slate-800 border-red-500/30">
          <CardHeader>
            <CardTitle className="text-2xl text-red-300 flex items-center gap-2">
              <AlertCircle className="h-6 w-6" />
              Invalid Reset Link
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <p className="text-slate-300">
              This password reset link is invalid or has expired. Please request a new one.
            </p>
            <Button
              onClick={() => window.location.href = "https://backend.rentapog.com/login"}
              className="w-full bg-cyan-600 hover:bg-cyan-700 text-white font-bold h-10"
            >
              Back to Login
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 to-slate-950 flex items-center justify-center p-4">
      <Card className="w-full max-w-md bg-slate-800 border-cyan-500/30">
        <CardHeader>
          <CardTitle className="text-2xl text-cyan-300 flex items-center gap-2">
            <Lock className="h-6 w-6" />
            Set New Password
          </CardTitle>
          <p className="text-slate-400 text-sm mt-2">
            Enter your new password below.
          </p>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit} className="space-y-4">
            {error && (
              <div className="flex gap-2 p-3 bg-red-500/10 border border-red-500/30 rounded text-red-300 text-sm">
                <AlertCircle className="h-4 w-4 mt-0.5" />
                <span>{error}</span>
              </div>
            )}

            <div>
              <label className="block text-sm font-medium text-slate-300 mb-2">
                New Password
              </label>
              <Input
                type="password"
                placeholder="********"
                value={newPassword}
                onChange={(e) => setNewPassword(e.target.value)}
                className="bg-slate-700 border-slate-600 text-white placeholder-slate-500"
                data-testid="input-new-password"
                disabled={loading}
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-300 mb-2">
                Confirm New Password
              </label>
              <Input
                type="password"
                placeholder="********"
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                className="bg-slate-700 border-slate-600 text-white placeholder-slate-500"
                data-testid="input-confirm-password"
                disabled={loading}
              />
            </div>

            <Button
              type="submit"
              disabled={loading}
              className="w-full bg-cyan-600 hover:bg-cyan-700 text-white font-bold h-10"
              data-testid="button-reset-password"
            >
              {loading ? "Resetting..." : "Reset Password"}
            </Button>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

client/src/pages/ABTestingAdmin.tsx.content:
import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { useToast } from "@/hooks/use-toast";
import { ArrowLeft, Plus, Play, Pause, Trophy, BarChart3, Eye } from "lucide-react";
import { Link } from "wouter";

interface AbVariant {
  id: number;
  name: string;
  weight: number;
  isControl: boolean;
  content: {
    headline?: string;
    subheadline?: string;
    cta?: string;
    buttonColor?: string;
    description?: string;
  };
  impressions: number;
  conversions: number;
  revenue: number;
}

interface AbTest {
  id: number;
  name: string;
  targetPage: string;
  status: string;
  successMetric: string;
  minSampleSize: number;
  winnerVariantId: number | null;
  createdAt: string;
  startedAt: string | null;
  completedAt: string | null;
  variants: AbVariant[];
}

export default function ABTestingAdmin() {
  const [tests, setTests] = useState<AbTest[]>([]);
  const [loading, setLoading] = useState(true);
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [selectedTest, setSelectedTest] = useState<AbTest | null>(null);
  const [analytics, setAnalytics] = useState<any>(null);
  const { toast } = useToast();

  const [newTest, setNewTest] = useState({
    name: "",
    targetPage: "packages",
    successMetric: "conversion",
    minSampleSize: 100,
    variants: [
      { name: "Control", isControl: true, weight: 50, content: { headline: "", subheadline: "", cta: "" } },
      { name: "Variant A", isControl: false, weight: 50, content: { headline: "", subheadline: "", cta: "" } },
    ],
  });

  useEffect(() => {
    fetchTests();
  }, []);

  const fetchTests = async () => {
    try {
      const res = await fetch("/api/admin/ab/tests");
      if (res.ok) {
        const data = await res.json();
        setTests(data);
      }
    } catch (error) {
      console.error("Failed to fetch tests:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchAnalytics = async (testId: number) => {
    try {
      const res = await fetch(`/api/admin/ab/tests/${testId}/analytics`);
      if (res.ok) {
        const data = await res.json();
        setAnalytics(data);
      }
    } catch (error) {
      console.error("Failed to fetch analytics:", error);
    }
  };

  const createTest = async () => {
    try {
      const res = await fetch("/api/admin/ab/tests", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newTest),
      });

      if (res.ok) {
        toast({ title: "Test created", description: "Your A/B test has been created successfully." });
        setShowCreateForm(false);
        setNewTest({
          name: "",
          targetPage: "packages",
          successMetric: "conversion",
          minSampleSize: 100,
          variants: [
            { name: "Control", isControl: true, weight: 50, content: { headline: "", subheadline: "", cta: "" } },
            { name: "Variant A", isControl: false, weight: 50, content: { headline: "", subheadline: "", cta: "" } },
          ],
        });
        fetchTests();
      } else {
        const data = await res.json();
        toast({ title: "Error", description: data.error || "Failed to create test" });
      }
    } catch (error) {
      toast({ title: "Error", description: "Failed to create test" });
    }
  };

  const updateTestStatus = async (testId: number, status: string) => {
    try {
      const res = await fetch(`/api/admin/ab/tests/${testId}/status`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status }),
      });

      if (res.ok) {
        toast({ title: "Status updated", description: `Test status changed to ${status}` });
        fetchTests();
      }
    } catch (error) {
      toast({ title: "Error", description: "Failed to update status" });
    }
  };

  const declareWinner = async (testId: number, variantId: number) => {
    try {
      const res = await fetch(`/api/admin/ab/tests/${testId}/winner`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ variantId }),
      });

      if (res.ok) {
        toast({ title: "Winner declared!", description: "The test has been completed." });
        fetchTests();
        setSelectedTest(null);
        setAnalytics(null);
      }
    } catch (error) {
      toast({ title: "Error", description: "Failed to declare winner" });
    }
  };

  const addVariant = () => {
    setNewTest({
      ...newTest,
      variants: [
        ...newTest.variants,
        { 
          name: `Variant ${String.fromCharCode(65 + newTest.variants.length - 1)}`, 
          isControl: false, 
          weight: Math.floor(100 / (newTest.variants.length + 1)), 
          content: { headline: "", subheadline: "", cta: "" } 
        },
      ],
    });
  };

  const updateVariant = (index: number, field: string, value: any) => {
    const variants = [...newTest.variants];
    if (field.startsWith("content.")) {
      const contentField = field.replace("content.", "");
      variants[index] = {
        ...variants[index],
        content: { ...variants[index].content, [contentField]: value },
      };
    } else {
      variants[index] = { ...variants[index], [field]: value };
    }
    setNewTest({ ...newTest, variants });
  };

  const getStatusBadge = (status: string) => {
    const colors: Record<string, string> = {
      draft: "bg-gray-100 text-gray-800",
      running: "bg-green-100 text-green-800",
      paused: "bg-yellow-100 text-yellow-800",
      completed: "bg-blue-100 text-blue-800",
    };
    return colors[status] || "bg-gray-100 text-gray-800";
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">Loading A/B tests...</div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-6xl mx-auto">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center gap-4">
            <Link href="/backoffice">
              <Button variant="outline" size="sm" data-testid="button-back">
                <ArrowLeft className="w-4 h-4 mr-2" />
                Back to Backoffice
              </Button>
            </Link>
            <h1 className="text-2xl font-bold text-gray-900">A/B Testing Dashboard</h1>
          </div>
          <Button onClick={() => setShowCreateForm(true)} data-testid="button-create-test">
            <Plus className="w-4 h-4 mr-2" />
            Create New Test
          </Button>
        </div>

        {showCreateForm && (
          <Card className="mb-6">
            <CardHeader>
              <CardTitle>Create New A/B Test</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium mb-1">Test Name</label>
                  <Input
                    value={newTest.name}
                    onChange={(e) => setNewTest({ ...newTest, name: e.target.value })}
                    placeholder="e.g., Homepage Headline Test"
                    data-testid="input-test-name"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium mb-1">Target Page</label>
                  <select
                    className="w-full px-3 py-2 border rounded-md"
                    value={newTest.targetPage}
                    onChange={(e) => setNewTest({ ...newTest, targetPage: e.target.value })}
                    data-testid="select-target-page"
                  >
                    <option value="packages">Packages Page</option>
                    <option value="branded-affiliate">Branded Affiliate Page</option>
                    <option value="home">Home Page</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium mb-1">Success Metric</label>
                  <select
                    className="w-full px-3 py-2 border rounded-md"
                    value={newTest.successMetric}
                    onChange={(e) => setNewTest({ ...newTest, successMetric: e.target.value })}
                    data-testid="select-success-metric"
                  >
                    <option value="conversion">Conversion Rate</option>
                    <option value="purchase">Purchase</option>
                    <option value="signup">Signup</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium mb-1">Min Sample Size (per variant)</label>
                  <Input
                    type="number"
                    value={newTest.minSampleSize}
                    onChange={(e) => setNewTest({ ...newTest, minSampleSize: parseInt(e.target.value) || 100 })}
                    data-testid="input-sample-size"
                  />
                </div>
              </div>

              <div className="border-t pt-4">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="font-semibold">Variants</h3>
                  <Button variant="outline" size="sm" onClick={addVariant} data-testid="button-add-variant">
                    <Plus className="w-4 h-4 mr-1" />
                    Add Variant
                  </Button>
                </div>

                {newTest.variants.map((variant, index) => (
                  <div key={index} className="border rounded-lg p-4 mb-4">
                    <div className="flex items-center gap-4 mb-3">
                      <Input
                        className="w-40"
                        value={variant.name}
                        onChange={(e) => updateVariant(index, "name", e.target.value)}
                        placeholder="Variant name"
                        data-testid={`input-variant-name-${index}`}
                      />
                      <span className="text-sm text-gray-500">Weight:</span>
                      <Input
                        type="number"
                        className="w-20"
                        value={variant.weight}
                        onChange={(e) => updateVariant(index, "weight", parseInt(e.target.value) || 0)}
                        data-testid={`input-variant-weight-${index}`}
                      />
                      <span className="text-sm text-gray-500">%</span>
                      {variant.isControl && (
                        <span className="bg-blue-100 text-blue-800 text-xs px-2 py-1 rounded">Control</span>
                      )}
                    </div>
                    <div className="grid grid-cols-3 gap-3">
                      <div>
                        <label className="block text-xs text-gray-500 mb-1">Headline</label>
                        <Input
                          value={variant.content.headline || ""}
                          onChange={(e) => updateVariant(index, "content.headline", e.target.value)}
                          placeholder="Custom headline"
                          data-testid={`input-variant-headline-${index}`}
                        />
                      </div>
                      <div>
                        <label className="block text-xs text-gray-500 mb-1">Subheadline</label>
                        <Input
                          value={variant.content.subheadline || ""}
                          onChange={(e) => updateVariant(index, "content.subheadline", e.target.value)}
                          placeholder="Custom subheadline"
                          data-testid={`input-variant-subheadline-${index}`}
                        />
                      </div>
                      <div>
                        <label className="block text-xs text-gray-500 mb-1">CTA Button Text</label>
                        <Input
                          value={variant.content.cta || ""}
                          onChange={(e) => updateVariant(index, "content.cta", e.target.value)}
                          placeholder="Custom CTA"
                          data-testid={`input-variant-cta-${index}`}
                        />
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              <div className="flex gap-2 justify-end">
                <Button variant="outline" onClick={() => setShowCreateForm(false)} data-testid="button-cancel">
                  Cancel
                </Button>
                <Button onClick={createTest} disabled={!newTest.name} data-testid="button-save-test">
                  Create Test
                </Button>
              </div>
            </CardContent>
          </Card>
        )}

        {selectedTest && analytics && (
          <Card className="mb-6">
            <CardHeader>
              <div className="flex items-center justify-between">
                <CardTitle>Analytics: {selectedTest.name}</CardTitle>
                <Button variant="outline" size="sm" onClick={() => { setSelectedTest(null); setAnalytics(null); }}>
                  Close
                </Button>
              </div>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
                {analytics.analytics.map((v: any) => (
                  <div key={v.id} className={`border rounded-lg p-4 ${v.isControl ? 'border-blue-300 bg-blue-50' : ''}`}>
                    <div className="flex items-center justify-between mb-2">
                      <span className="font-semibold">{v.name}</span>
                      {v.isControl && <span className="text-xs bg-blue-100 text-blue-800 px-2 py-1 rounded">Control</span>}
                    </div>
                    <div className="grid grid-cols-2 gap-2 text-sm">
                      <div>
                        <div className="text-gray-500">Impressions</div>
                        <div className="font-bold">{v.impressions.toLocaleString()}</div>
                      </div>
                      <div>
                        <div className="text-gray-500">Conversions</div>
                        <div className="font-bold">{v.conversions.toLocaleString()}</div>
                      </div>
                      <div>
                        <div className="text-gray-500">Rate</div>
                        <div className="font-bold text-green-600">{v.conversionRate}%</div>
                      </div>
                      <div>
                        <div className="text-gray-500">Revenue</div>
                        <div className="font-bold">${v.revenue.toFixed(2)}</div>
                      </div>
                    </div>
                    {selectedTest.status === "running" && (
                      <Button
                        size="sm"
                        variant="outline"
                        className="w-full mt-3"
                        onClick={() => declareWinner(selectedTest.id, v.id)}
                        data-testid={`button-declare-winner-${v.id}`}
                      >
                        <Trophy className="w-4 h-4 mr-1" />
                        Declare Winner
                      </Button>
                    )}
                  </div>
                ))}
              </div>
              {analytics.winner && (
                <div className="bg-green-50 border border-green-200 rounded-lg p-4">
                  <div className="flex items-center gap-2 text-green-800">
                    <Trophy className="w-5 h-5" />
                    <span className="font-semibold">Winner: {analytics.winner.name}</span>
                    <span className="text-sm">({analytics.winner.conversionRate}% conversion rate)</span>
                  </div>
                </div>
              )}
            </CardContent>
          </Card>
        )}

        <div className="grid gap-4">
          {tests.length === 0 ? (
            <Card>
              <CardContent className="py-12 text-center">
                <BarChart3 className="w-12 h-12 mx-auto text-gray-400 mb-4" />
                <p className="text-gray-500">No A/B tests yet. Create your first test to start optimizing!</p>
              </CardContent>
            </Card>
          ) : (
            tests.map((test) => (
              <Card key={test.id}>
                <CardContent className="py-4">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-4">
                      <div>
                        <h3 className="font-semibold">{test.name}</h3>
                        <p className="text-sm text-gray-500">
                          Target: {test.targetPage} | Metric: {test.successMetric} | Min samples: {test.minSampleSize}
                        </p>
                      </div>
                      <span className={`px-2 py-1 rounded text-xs font-medium ${getStatusBadge(test.status)}`}>
                        {test.status.toUpperCase()}
                      </span>
                    </div>
                    <div className="flex items-center gap-2">
                      {test.status === "draft" && (
                        <Button
                          size="sm"
                          onClick={() => updateTestStatus(test.id, "running")}
                          data-testid={`button-start-test-${test.id}`}
                        >
                          <Play className="w-4 h-4 mr-1" />
                          Start
                        </Button>
                      )}
                      {test.status === "running" && (
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => updateTestStatus(test.id, "paused")}
                          data-testid={`button-pause-test-${test.id}`}
                        >
                          <Pause className="w-4 h-4 mr-1" />
                          Pause
                        </Button>
                      )}
                      {test.status === "paused" && (
                        <Button
                          size="sm"
                          onClick={() => updateTestStatus(test.id, "running")}
                          data-testid={`button-resume-test-${test.id}`}
                        >
                          <Play className="w-4 h-4 mr-1" />
                          Resume
                        </Button>
                      )}
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() => {
                          setSelectedTest(test);
                          fetchAnalytics(test.id);
                        }}
                        data-testid={`button-view-analytics-${test.id}`}
                      >
                        <Eye className="w-4 h-4 mr-1" />
                        Analytics
                      </Button>
                    </div>
                  </div>
                  <div className="mt-3 flex gap-2">
                    {test.variants?.map((v: AbVariant) => (
                      <div
                        key={v.id}
                        className={`text-xs px-2 py-1 rounded ${
                          v.isControl ? 'bg-blue-100 text-blue-800' : 'bg-gray-100 text-gray-800'
                        } ${test.winnerVariantId === v.id ? 'ring-2 ring-green-500' : ''}`}
                      >
                        {v.name}: {v.impressions} imp / {v.conversions} conv
                        {test.winnerVariantId === v.id && <Trophy className="w-3 h-3 inline ml-1" />}
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>
            ))
          )}
        </div>
      </div>
    </div>
  );
}

