import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { useToast } from "@/hooks/use-toast";
import { Facebook, Sparkles, Send, LinkIcon, CheckCircle2, XCircle, Loader2, ExternalLink } from "lucide-react";

interface FacebookAdsProps {
  userId: string;
}

export default function FacebookAds({ userId }: FacebookAdsProps) {
  const { toast } = useToast();
  const [fbStatus, setFbStatus] = useState<{
    connected: boolean;
    pageName: string | null;
    pageId: string | null;
  }>({ connected: false, pageName: null, pageId: null });
  const [loading, setLoading] = useState(true);
  const [prompt, setPrompt] = useState("");
  const [generatedAd, setGeneratedAd] = useState("");
  const [generating, setGenerating] = useState(false);
  const [posting, setPosting] = useState(false);
  const [lastPostUrl, setLastPostUrl] = useState<string | null>(null);

  useEffect(() => {
    const checkFacebookStatus = async () => {
      try {
        const res = await fetch(`/api/facebook/status/${userId}`);
        if (res.ok) {
          const data = await res.json();
          setFbStatus(data);
        }
      } catch (err) {
        console.error("Failed to check Facebook status:", err);
      } finally {
        setLoading(false);
      }
    };

    if (userId) {
      checkFacebookStatus();
    }
  }, [userId]);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    if (params.get("fb_success") === "true") {
      toast({
        title: "Facebook Connected!",
        description: "Your Facebook page is now connected.",
      });
      window.history.replaceState({}, "", window.location.pathname);
      setLoading(true);
      fetch(`/api/facebook/status/${userId}`)
        .then((res) => res.json())
        .then((data) => setFbStatus(data))
        .finally(() => setLoading(false));
    }
    if (params.get("fb_error")) {
      const errorMap: Record<string, string> = {
        access_denied: "Facebook access was denied.",
        no_pages: "No Facebook pages found. You need a Facebook Page to post ads.",
        token_error: "Failed to get access token from Facebook.",
        callback_error: "Connection failed. Please try again.",
      };
      toast({
        title: "Connection Failed",
        description: errorMap[params.get("fb_error") || ""] || "Something went wrong.",
        variant: "destructive",
      });
      window.history.replaceState({}, "", window.location.pathname);
    }
  }, [toast, userId]);

  const handleConnectFacebook = () => {
    window.location.href = `/api/facebook/auth?userId=${userId}`;
  };

  const handleDisconnect = async () => {
    try {
      const res = await fetch(`/api/facebook/disconnect/${userId}`, {
        method: "POST",
      });
      if (res.ok) {
        setFbStatus({ connected: false, pageName: null, pageId: null });
        toast({
          title: "Disconnected",
          description: "Facebook page has been disconnected.",
        });
      }
    } catch (err) {
      toast({
        title: "Error",
        description: "Failed to disconnect Facebook.",
        variant: "destructive",
      });
    }
  };

  const handleGenerateAd = async () => {
    if (!prompt.trim()) {
      toast({
        title: "Enter a prompt",
        description: "Tell Coey what kind of ad you want to create.",
        variant: "destructive",
      });
      return;
    }

    setGenerating(true);
    setGeneratedAd("");
    setLastPostUrl(null);

    try {
      const res = await fetch("/api/coey/facebook-ad", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ userId, prompt, autoPost: false }),
      });

      const data = await res.json();
      if (data.success && data.adCopy) {
        setGeneratedAd(data.adCopy);
        toast({
          title: "Ad Generated!",
          description: "Review your ad below. Edit if needed, then post to Facebook.",
        });
      } else {
        throw new Error(data.error || "Failed to generate ad");
      }
    } catch (err: any) {
      toast({
        title: "Generation Failed",
        description: err.message || "Failed to generate ad.",
        variant: "destructive",
      });
    } finally {
      setGenerating(false);
    }
  };

  const handlePostToFacebook = async () => {
    if (!generatedAd.trim()) {
      toast({
        title: "No ad to post",
        description: "Generate an ad first.",
        variant: "destructive",
      });
      return;
    }

    if (!fbStatus.connected) {
      toast({
        title: "Not Connected",
        description: "Connect your Facebook page first.",
        variant: "destructive",
      });
      return;
    }

    setPosting(true);
    try {
      const res = await fetch("/api/facebook/post", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ userId, message: generatedAd }),
      });

      const data = await res.json();
      if (data.success) {
        setLastPostUrl(data.pageUrl);
        toast({
          title: "Posted to Facebook!",
          description: `Your ad is now live on ${fbStatus.pageName}.`,
        });
      } else {
        throw new Error(data.error || "Failed to post");
      }
    } catch (err: any) {
      toast({
        title: "Posting Failed",
        description: err.message || "Failed to post to Facebook.",
        variant: "destructive",
      });
    } finally {
      setPosting(false);
    }
  };

  const handleGenerateAndPost = async () => {
    if (!prompt.trim()) {
      toast({
        title: "Enter a prompt",
        description: "Tell Coey what kind of ad you want to create.",
        variant: "destructive",
      });
      return;
    }

    if (!fbStatus.connected) {
      toast({
        title: "Not Connected",
        description: "Connect your Facebook page first.",
        variant: "destructive",
      });
      return;
    }

    setGenerating(true);
    setGeneratedAd("");
    setLastPostUrl(null);

    try {
      const res = await fetch("/api/coey/facebook-ad", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ userId, prompt, autoPost: true }),
      });

      const data = await res.json();
      if (data.success && data.adCopy) {
        setGeneratedAd(data.adCopy);
        if (data.posted) {
          setLastPostUrl(data.pageUrl);
          toast({
            title: "Ad Created & Posted!",
            description: `Your ad is now live on ${fbStatus.pageName}.`,
          });
        } else if (data.postError) {
          toast({
            title: "Ad Generated (Post Failed)",
            description: data.postError,
            variant: "destructive",
          });
        }
      } else {
        throw new Error(data.error || "Failed to generate ad");
      }
    } catch (err: any) {
      toast({
        title: "Failed",
        description: err.message || "Failed to generate and post ad.",
        variant: "destructive",
      });
    } finally {
      setGenerating(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="h-6 w-6 animate-spin text-blue-600" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-bold mb-2 flex items-center gap-2">
          <Facebook className="h-6 w-6 text-blue-600" />
          Facebook Ads with Coey
        </h2>
        <p className="text-muted-foreground">
          Let Coey write high-converting Facebook ads and post them directly to your page.
        </p>
      </div>

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-lg">
            <LinkIcon className="h-5 w-5" />
            Facebook Connection
          </CardTitle>
        </CardHeader>
        <CardContent>
          {fbStatus.connected ? (
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <CheckCircle2 className="h-5 w-5 text-green-600" />
                <div>
                  <p className="font-medium">Connected to: {fbStatus.pageName}</p>
                  <p className="text-sm text-muted-foreground">Ready to post ads</p>
                </div>
              </div>
              <Button variant="outline" size="sm" onClick={handleDisconnect} data-testid="button-disconnect-fb">
                Disconnect
              </Button>
            </div>
          ) : (
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <XCircle className="h-5 w-5 text-gray-400" />
                <div>
                  <p className="font-medium">Not Connected</p>
                  <p className="text-sm text-muted-foreground">Connect your Facebook page to post ads</p>
                </div>
              </div>
              <Button onClick={handleConnectFacebook} className="gap-2 bg-blue-600 hover:bg-blue-700" data-testid="button-connect-fb">
                <Facebook className="h-4 w-4" />
                Connect Facebook
              </Button>
            </div>
          )}
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-lg">
            <Sparkles className="h-5 w-5 text-amber-500" />
            Create Your Ad
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <label className="text-sm font-medium">What kind of ad do you want?</label>
            <Textarea
              placeholder="E.g., Write a Facebook ad promoting daily domain rentals for affiliate marketers. Focus on passive income and easy setup."
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              className="min-h-[100px]"
              data-testid="input-fb-ad-prompt"
            />
          </div>

          <div className="flex gap-2 flex-wrap">
            <Button
              onClick={handleGenerateAd}
              disabled={generating || !prompt.trim()}
              className="gap-2"
              variant="outline"
              data-testid="button-generate-ad"
            >
              {generating ? (
                <Loader2 className="h-4 w-4 animate-spin" />
              ) : (
                <Sparkles className="h-4 w-4" />
              )}
              Generate Ad
            </Button>

            {fbStatus.connected && (
              <Button
                onClick={handleGenerateAndPost}
                disabled={generating || !prompt.trim()}
                className="gap-2 bg-blue-600 hover:bg-blue-700"
                data-testid="button-generate-and-post"
              >
                {generating ? (
                  <Loader2 className="h-4 w-4 animate-spin" />
                ) : (
                  <>
                    <Sparkles className="h-4 w-4" />
                    <Send className="h-4 w-4" />
                  </>
                )}
                Generate & Post
              </Button>
            )}
          </div>
        </CardContent>
      </Card>

      {generatedAd && (
        <Card className="border-2 border-blue-200">
          <CardHeader className="bg-blue-50">
            <CardTitle className="text-lg">Your Facebook Ad</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4 pt-4">
            <Textarea
              value={generatedAd}
              onChange={(e) => setGeneratedAd(e.target.value)}
              className="min-h-[150px]"
              data-testid="textarea-generated-ad"
            />

            <div className="flex items-center gap-4">
              {fbStatus.connected && !lastPostUrl && (
                <Button
                  onClick={handlePostToFacebook}
                  disabled={posting}
                  className="gap-2 bg-blue-600 hover:bg-blue-700"
                  data-testid="button-post-to-fb"
                >
                  {posting ? (
                    <Loader2 className="h-4 w-4 animate-spin" />
                  ) : (
                    <Send className="h-4 w-4" />
                  )}
                  Post to Facebook
                </Button>
              )}

              {lastPostUrl && (
                <a
                  href={lastPostUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="flex items-center gap-2 text-blue-600 hover:underline"
                  data-testid="link-view-post"
                >
                  <ExternalLink className="h-4 w-4" />
                  View your post on Facebook
                </a>
              )}
            </div>
          </CardContent>
        </Card>
      )}

      <Card className="bg-amber-50 border-amber-200">
        <CardHeader>
          <CardTitle className="text-amber-900 text-sm">Tips for Great Facebook Ads</CardTitle>
        </CardHeader>
        <CardContent className="text-sm text-amber-800 space-y-2">
          <p>• Keep your prompt specific - mention your target audience and key benefits</p>
          <p>• Coey will automatically include emojis and a call-to-action</p>
          <p>• Your affiliate link will be attached when posting</p>
          <p>• You can edit the generated ad before posting</p>
        </CardContent>
      </Card>
    </div>
  );
}

client/src/hooks/use-ab-test.ts.content:
import { useState, useEffect, useCallback } from "react";

export interface AbVariantContent {
  headline?: string;
  subheadline?: string;
  cta?: string;
  buttonColor?: string;
  description?: string;
  features?: string[];
  imageUrl?: string;
}

interface AbTestState {
  variant: AbVariantContent | null;
  variantId: number | null;
  testId: number | null;
  assignmentId: number | null;
  isLoading: boolean;
  error: string | null;
}

const VISITOR_ID_KEY = "ab_visitor_id";

function getOrCreateVisitorId(): string {
  let visitorId = localStorage.getItem(VISITOR_ID_KEY);
  if (!visitorId) {
    visitorId = `v_${Date.now()}_${Math.random().toString(36).substring(2, 11)}`;
    localStorage.setItem(VISITOR_ID_KEY, visitorId);
  }
  return visitorId;
}

export function useAbTest(targetPage: string, userId?: string) {
  const [state, setState] = useState<AbTestState>({
    variant: null,
    variantId: null,
    testId: null,
    assignmentId: null,
    isLoading: true,
    error: null,
  });

  useEffect(() => {
    async function loadVariant() {
      try {
        const visitorId = getOrCreateVisitorId();

        const response = await fetch("/api/ab/assign", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ targetPage, visitorId, userId }),
        });

        if (!response.ok) {
          throw new Error("Failed to get variant");
        }

        const data = await response.json();

        setState({
          variant: data.variant,
          variantId: data.variantId,
          testId: data.testId,
          assignmentId: data.assignmentId,
          isLoading: false,
          error: null,
        });
      } catch (error: any) {
        console.error("[useAbTest] Error:", error);
        setState((prev) => ({
          ...prev,
          isLoading: false,
          error: error?.message || "Failed to load variant",
        }));
      }
    }

    loadVariant();
  }, [targetPage, userId]);

  const trackConversion = useCallback(
    async (revenue?: number, eventType?: string) => {
      if (!state.assignmentId) {
        console.warn("[useAbTest] No assignmentId, cannot track conversion");
        return false;
      }

      try {
        const response = await fetch("/api/ab/convert", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            assignmentId: state.assignmentId,
            revenue,
            eventType,
          }),
        });

        if (!response.ok) {
          throw new Error("Failed to track conversion");
        }

        return true;
      } catch (error: any) {
        console.error("[useAbTest] Conversion tracking error:", error);
        return false;
      }
    },
    [state.assignmentId]
  );

  return {
    ...state,
    trackConversion,
    hasActiveTest: state.testId !== null && state.variant !== null,
  };
}

