      config
    );

    if (result.success && result.result) {
      return result.result.map((d: any) => ({
        name: d.name,
        status: d.status || 'pending',
      }));
    }

    return [];
  } catch (error) {
    console.error("[Cloudflare Pages] Get custom domains error:", error);
    return [];
  }
}

